<?php require 'config.php';require_login();if(is_admin()){header('Location: admin.php');exit;}if(!isset($_SESSION['cart']))$_SESSION['cart']=[];if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['product_id'])){$id=(int)$_POST['product_id'];$qty=max(1,(int)($_POST['qty']??1));$s=$pdo->prepare("SELECT stock FROM products WHERE id=? AND is_active=1");$s->execute([$id]);$p=$s->fetch();if($p&&$p['stock']>0){$_SESSION['cart'][$id]=min($p['stock'],($_SESSION['cart'][$id]??0)+$qty);$_SESSION['choices'][$id]=['size'=>$_POST['size']??'','color'=>$_POST['color']??'','design'=>$_POST['design']??''];}header('Location: cart.php');exit;}if(isset($_GET['remove'])){unset($_SESSION['cart'][(int)$_GET['remove']],$_SESSION['choices'][(int)$_GET['remove']]);header('Location: cart.php');exit;}$items=[];$total=0;if($_SESSION['cart']){$ids=array_keys($_SESSION['cart']);$in=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT * FROM products WHERE id IN ($in)");$s->execute($ids);$items=$s->fetchAll();foreach($items as $p)$total+=$p['price']*$_SESSION['cart'][$p['id']];}$page_title='Your cart';require 'header.php';?>
<section class="wrap"><h1>Your shopping bag</h1><?php if(!$items):?><p class="muted">Your cart is empty. <a href="shop.php">Explore the collection.</a></p><?php else:?><table class="table"><tr><th>Item</th><th>Options</th><th>Qty</th><th>Subtotal</th><th></th></tr><?php foreach($items as $p):$q=$_SESSION['cart'][$p['id']];$ch=$_SESSION['choices'][$p['id']]??[];?><tr><td><?=e($p['name'])?></td><td><?=e(($ch['size']??''). ' / '.($ch['color']??''))?></td><td><?=$q?></td><td><?=money($p['price']*$q)?></td><td><a href="cart.php?remove=<?=$p['id']?>">Remove</a></td></tr><?php endforeach;?></table><h2>Total: <?=money($total)?></h2><a class="btn" href="checkout.php">Proceed to checkout</a><?php endif;?></section><?php require 'footer.php';?>
